using Microsoft.EntityFrameworkCore;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.IO.Compression;
using System.Xml;
using System.Xml.Linq;

namespace Society.Api;

public static class MemberImportEndpoints
{
    public static void Map(RouteGroupBuilder t)
    {
        t.MapPost("/imports/preview", async (Guid tenant, ImportRequest r, AppDb db, Access a, MembershipService s) => { await a.Require(tenant, "members.import", r.ChapterId); await a.Require(tenant, "members.write", r.ChapterId); await s.Chapter(tenant, r.ChapterId); await s.Category(tenant, r.CategoryId); var records = Read(r.Format, r.Content); if (records.Count < 2 || records.Count > 10001) throw new DomainException("Import a header and 1–10,000 data rows"); var headers = records[0]; string Value(string[] row, string key) { var mapped = r.Mapping.GetValueOrDefault(key, key); var index = Array.FindIndex(headers, x => x.Trim().Equals(mapped, StringComparison.OrdinalIgnoreCase)); return index >= 0 && index < row.Length ? row[index].Trim() : ""; } var job = new MemberImportJob { TenantId = tenant, ChapterId = r.ChapterId, CategoryId = r.CategoryId, ActorId = a.UserId, Total = records.Count - 1 }; db.MemberImportJobs.Add(job); var emails = new HashSet<string>(StringComparer.OrdinalIgnoreCase); var numbers = new HashSet<string>(StringComparer.OrdinalIgnoreCase); for (int i = 1; i < records.Count; i++) { var row = records[i]; var data = new JsonObject { ["fullName"] = Value(row, "fullName"), ["email"] = Value(row, "email"), ["phone"] = Value(row, "phone"), ["city"] = Value(row, "city"), ["number"] = Value(row, "number") }; string error = ""; var name = data["fullName"]!.GetValue<string>(); var email = data["email"]!.GetValue<string>(); var number = data["number"]!.GetValue<string>(); if (string.IsNullOrWhiteSpace(name) || name.Length > 160) error = "Full name is required (up to 160 characters)"; else if (email != "" && !System.Net.Mail.MailAddress.TryCreate(email, out _)) error = "Invalid email"; else if (Value(row, "phone") != "" && !System.Text.RegularExpressions.Regex.IsMatch(Value(row, "phone"), "^[+()0-9 .-]{3,30}$")) error = "Invalid mobile number"; else if (number != "" && (number.Length > 40 || !System.Text.RegularExpressions.Regex.IsMatch(number, "^[A-Za-z0-9_-]+$"))) error = "Invalid member ID"; else if (email != "" && !emails.Add(email)) error = "Duplicate email in file; review the identity before importing"; else if (number != "" && !numbers.Add(number)) error = "Duplicate member ID in file"; db.MemberImportRows.Add(new MemberImportRow { TenantId = tenant, JobId = job.Id, Row = i, Data = data.ToJsonString(), Error = error, Status = error == "" ? "Pending" : "Invalid" }); } a.Audit(tenant, "membership.import.preview", job.Id, new { job.Total }); await db.SaveChangesAsync(); return Results.Ok(new { job.Id, job.Total, headers }); });
        t.MapGet("/imports", async (Guid tenant, AppDb db, Access a) => { await a.Member(tenant); var units = a.Visible(tenant, "members.import").Select(x => x.Id); return await db.MemberImportJobs.Where(x => x.TenantId == tenant && units.Contains(x.ChapterId)).OrderByDescending(x => x.CreatedAt).Take(30).Select(x => new { x.Id, x.Status, x.Total, x.Processed, x.ChapterId, x.CreatedAt }).ToListAsync(); });
        t.MapGet("/imports/{id:guid}", async (Guid tenant, Guid id, int? page, AppDb db, Access a) => { var job = await db.MemberImportJobs.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Id == id) ?? throw new AccessDeniedException(); await a.Require(tenant, "members.import", job.ChapterId); return Results.Ok(new { job.Id, job.Status, job.Total, job.Processed,failedRows=await db.MemberImportRows.CountAsync(r=>r.TenantId==tenant&&r.JobId==id&&r.Status=="Failed"), rows = await db.MemberImportRows.Where(x => x.TenantId == tenant && x.JobId == id).OrderBy(x => x.Row).Skip(Math.Clamp((page ?? 1) - 1, 0, 1000000) * 50).Take(50).Select(x => new { x.Id, x.Row, x.Data, x.Status, x.Error, x.MembershipId }).ToListAsync() }); });
        t.MapPost("/imports/{id:guid}/confirm", async (Guid tenant, Guid id, AppDb db, Access a) => { await using var tx = await db.Database.BeginTransactionAsync(); var job = await db.MemberImportJobs.FromSqlInterpolated($"SELECT * FROM \"MemberImportJobs\" WHERE \"TenantId\"={tenant} AND \"Id\"={id} FOR UPDATE").SingleOrDefaultAsync() ?? throw new AccessDeniedException(); await a.Require(tenant, "members.import", job.ChapterId); await a.Require(tenant, "members.write", job.ChapterId); if (job.Status != "Preview") throw new DomainException("Import was already confirmed"); job.Status = "Queued"; job.ActorId = a.UserId; a.Audit(tenant, "membership.import.confirmed", id); await db.SaveChangesAsync(); await tx.CommitAsync(); return Results.NoContent(); });
        t.MapPost("/imports/{id:guid}/retry",async(Guid tenant,Guid id,AppDb db,Access a)=>{await using var tx=await db.Database.BeginTransactionAsync();var job=await db.MemberImportJobs.FromSqlInterpolated($"SELECT * FROM \"MemberImportJobs\" WHERE \"TenantId\"={tenant} AND \"Id\"={id} FOR UPDATE").SingleOrDefaultAsync()??throw new AccessDeniedException();await a.Require(tenant,"members.import",job.ChapterId);await a.Require(tenant,"members.write",job.ChapterId);if(job.Status is "Queued" or "Processing" or "Preview")throw new DomainException("This job is not awaiting retry");var rows=await db.MemberImportRows.Where(r=>r.TenantId==tenant&&r.JobId==id&&r.Status=="Failed").ToListAsync();foreach(var row in rows){row.Status="Pending";row.Error="";}job.Status="Queued";job.ActorId=a.UserId;a.Audit(tenant,"membership.import.retried",id);await db.SaveChangesAsync();await tx.CommitAsync();return Results.NoContent();});
    }
    public static List<string[]> Read(string format, string content) { if (content.Length > 12000000) throw new DomainException("Import file is too large"); if (format.Equals("csv", StringComparison.OrdinalIgnoreCase)) return Csv(content); if (format.Equals("xlsx", StringComparison.OrdinalIgnoreCase)) return Xlsx(content); throw new DomainException("Use CSV or XLSX format"); }
    static List<string[]> Csv(string text) { text=text.TrimStart('\uFEFF'); var rows = new List<string[]>(); var row = new List<string>(); var field = new StringBuilder(); bool quoted = false; for (int i = 0; i < text.Length; i++) { char c = text[i]; if (c == '"') { if (quoted && i + 1 < text.Length && text[i + 1] == '"') { field.Append('"'); i++; } else quoted = !quoted; } else if (c == ',' && !quoted) { row.Add(field.ToString()); field.Clear(); } else if ((c == '\r' || c == '\n') && !quoted) { if (c == '\r' && i + 1 < text.Length && text[i + 1] == '\n') i++; row.Add(field.ToString()); field.Clear(); if (row.Any(x => x != "")) rows.Add(row.ToArray()); row.Clear(); if (rows.Count > 10001) throw new DomainException("Maximum 10,000 import rows"); } else field.Append(c); } if (quoted) throw new DomainException("CSV has an unclosed quoted field"); row.Add(field.ToString()); if (row.Any(x => x != "")) rows.Add(row.ToArray()); return rows; }
    static List<string[]> Xlsx(string content) { try { using var bytes = new MemoryStream(Convert.FromBase64String(content)); using var zip = new ZipArchive(bytes, ZipArchiveMode.Read); if (zip.Entries.Count > 200 || zip.Entries.Sum(e => e.Length) > 16000000) throw new DomainException("Excel workbook exceeds safe expansion limits"); XDocument Load(ZipArchiveEntry entry) { using var stream = entry.Open(); using var reader = XmlReader.Create(stream, new XmlReaderSettings { DtdProcessing = DtdProcessing.Prohibit, MaxCharactersInDocument = 16000000, XmlResolver = null }); return XDocument.Load(reader); } XNamespace ns = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"; var shared = new List<string>(); var strings = zip.GetEntry("xl/sharedStrings.xml"); if (strings != null) shared = Load(strings).Descendants(ns + "si").Select(x => string.Concat(x.Descendants(ns + "t").Select(t => t.Value))).ToList(); var sheet = zip.GetEntry("xl/worksheets/sheet1.xml") ?? throw new DomainException("Use a workbook with data in the first worksheet"); var rows = new List<string[]>(); foreach (var row in Load(sheet).Descendants(ns + "row")) { var values = new SortedDictionary<int, string>(); foreach (var cell in row.Elements(ns + "c")) { if (cell.Element(ns + "f") != null) throw new DomainException("Replace Excel formulas with values before importing"); var reference = cell.Attribute("r")?.Value ?? "A1"; int index = 0; foreach (char c in reference.TakeWhile(char.IsLetter)) index = checked(index * 26 + (char.ToUpperInvariant(c) - 'A' + 1)); if (index is < 1 or > 100) throw new DomainException("Use at most 100 columns"); var type = cell.Attribute("t")?.Value; var value = cell.Element(ns + "v")?.Value ?? string.Concat(cell.Descendants(ns + "t").Select(t => t.Value)); if (type == "s") value = shared[int.Parse(value)]; values[index - 1] = value; } if (values.Count > 0) { var cells = new string[values.Keys.Max() + 1]; Array.Fill(cells, ""); foreach (var pair in values) cells[pair.Key] = pair.Value; rows.Add(cells); } if (rows.Count > 10001) throw new DomainException("Maximum 10,000 import rows"); } return rows; } catch (DomainException) { throw; } catch { throw new DomainException("The XLSX file is invalid or unsupported"); } }
}

public class MembershipJobWorker(IServiceScopeFactory scopes,ILogger<MembershipJobWorker> logger):BackgroundService {
 protected override async Task ExecuteAsync(CancellationToken token){while(!token.IsCancellationRequested){try{if(await Tick(token)){await Task.Yield();continue;}}catch(Exception error){logger.LogWarning("Membership job cycle failed: {Type}",error.GetType().Name);}await Task.Delay(1000,token);}}
 async Task<bool> Tick(CancellationToken token){using var scope=scopes.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDb>();var service=scope.ServiceProvider.GetRequiredService<MembershipService>();await Transfers(db,service,token);await using var tx=await db.Database.BeginTransactionAsync(token);var job=await db.MemberImportJobs.FromSqlRaw("SELECT * FROM \"MemberImportJobs\" WHERE \"Status\" IN ('Queued','Processing') ORDER BY \"CreatedAt\" FOR UPDATE SKIP LOCKED LIMIT 1").AsEnumerableAsync(token);if(job==null){await tx.RollbackAsync(token);return false;}await MembershipService.Lock(db,job.TenantId);bool authorized=await db.Tenants.AnyAsync(t=>t.Id==job.TenantId&&t.Status!="Suspended",token)&&await Access.UnitsFor(db,job.TenantId,job.ActorId,"members.import").AnyAsync(u=>u.Id==job.ChapterId,token)&&await Access.UnitsFor(db,job.TenantId,job.ActorId,"members.write").AnyAsync(u=>u.Id==job.ChapterId,token);if(!authorized){job.Status="Blocked";await db.SaveChangesAsync(token);await tx.CommitAsync(token);return true;}try{await service.Chapter(job.TenantId,job.ChapterId);await service.Category(job.TenantId,job.CategoryId);}catch(DomainException){job.Status="Blocked";await db.SaveChangesAsync(token);await tx.CommitAsync(token);return true;}
 job.Status="Processing";var rows=await db.MemberImportRows.Where(r=>r.TenantId==job.TenantId&&r.JobId==job.Id&&r.Status=="Pending").OrderBy(r=>r.Row).Take(100).ToListAsync(token);var batch=rows.Select(r=>new{row=r,data=MembershipService.Json(r.Data)}).ToList();var emailValues=batch.Select(r=>r.data["email"]!.GetValue<string>().ToLowerInvariant()).Where(s=>s!="").Distinct().ToArray();var numberValues=batch.Select(r=>r.data["number"]!.GetValue<string>().ToUpperInvariant()).Where(s=>s!="").Distinct().ToArray();var numbers=(await db.Memberships.Where(m=>m.TenantId==job.TenantId&&numberValues.Contains(m.Number)).Select(m=>m.Number).ToListAsync(token)).ToHashSet(StringComparer.OrdinalIgnoreCase);var emails=(await db.Database.SqlQuery<string>($"SELECT lower(\"Profile\"->>'email') AS \"Value\" FROM \"Memberships\" WHERE \"TenantId\"={job.TenantId} AND lower(\"Profile\"->>'email')=ANY({emailValues})").ToListAsync(token)).ToHashSet(StringComparer.OrdinalIgnoreCase);
 foreach(var item in batch){var email=item.data["email"]!.GetValue<string>();var number=item.data["number"]!.GetValue<string>();try{if(number!=""&&numbers.Contains(number))throw new DomainException("Existing member ID; no record was overwritten");if(email!=""&&emails.Contains(email))throw new DomainException("Existing email; review and explicitly reuse the person identity");var member=service.ImportRecord(job.TenantId,job.ChapterId,job.CategoryId,item.data["fullName"]!.GetValue<string>(),number,item.data.ToJsonString(),job.ActorId);item.row.MembershipId=member.Id;item.row.Status="Imported";if(number!="")numbers.Add(number);if(email!="")emails.Add(email);}catch(DomainException error){item.row.Status="Failed";item.row.Error=error.Message;}}
 var rowIds=rows.Select(r=>r.Id).ToArray();job.Processed=await db.MemberImportRows.CountAsync(r=>r.JobId==job.Id&&r.Status!="Pending",token)+rows.Count;if(!await db.MemberImportRows.AnyAsync(r=>r.JobId==job.Id&&r.Status=="Pending"&&!rowIds.Contains(r.Id),token))job.Status="Complete";await db.SaveChangesAsync(token);await tx.CommitAsync(token);return true;
 }
 static async Task Transfers(AppDb db,MembershipService service,CancellationToken token){var due=await db.MembershipTransfers.Where(t=>t.Status=="Approved"&&t.EffectiveAt<=DateTimeOffset.UtcNow&&db.Tenants.Any(s=>s.Id==t.TenantId&&s.Status!="Suspended")).OrderBy(t=>t.EffectiveAt).Select(t=>new{t.Id,t.TenantId}).Take(10).ToListAsync(token);foreach(var item in due){await using var tx=await db.Database.BeginTransactionAsync(token);await MembershipService.Lock(db,item.TenantId);var transfer=await db.MembershipTransfers.FromSqlInterpolated($"SELECT * FROM \"MembershipTransfers\" WHERE \"Id\"={item.Id} FOR UPDATE").SingleAsync(token);try{await TransferEndpoints.Apply(transfer,db,service,transfer.RequestedBy);}catch(DomainException error){transfer.Status="Rejected";transfer.Notes+=" | Effective transfer blocked: "+error.Message;}await db.SaveChangesAsync(token);await tx.CommitAsync(token);}}
}
public static class ImportQueryExtensions {public static async Task<MemberImportJob?> AsEnumerableAsync(this IQueryable<MemberImportJob> query,CancellationToken token){await foreach(var job in query.AsAsyncEnumerable().WithCancellation(token))return job;return null;}}
